require 'socket'
require 'net/smtp'
require 'json'

module DistCache
  class Client
    PROTOCOL_VERSION = 2
    DEFAULT_TTL = 3600
    MAX_KEY_LENGTH = 250

    def initialize(servers:, notify_email: nil, smtp_host: 'localhost', smtp_port: 25)
      @servers = servers.map { |s| parse_server(s) }
      @notify_email = notify_email
      @smtp_host = smtp_host
      @smtp_port = smtp_port
      @connections = {}
      @shutdown = false
      @mutex = Mutex.new
      @pending_ops = []
      setup_signal_handlers
    end

    def get(key)
      raise "Client shut down" if @shutdown
      validate_key!(key)
      server = consistent_hash(key)
      send_command(server, build_get(key))
    end

    def set(key, value, ttl: DEFAULT_TTL)
      raise "Client shut down" if @shutdown
      validate_key!(key)
      server = consistent_hash(key)
      send_command(server, build_set(key, value, ttl))
    end

    def graceful_shutdown(reason: "maintenance")
      @shutdown = true
      @mutex.synchronize do
        drain_pending_operations
        close_all_connections
        notify_shutdown(reason) if @notify_email
      end
    end

    private

    def parse_server(server_str)
      host, port = server_str.split(':')
      { host: host, port: port.to_i }
    end

    def setup_signal_handlers
      Signal.trap('TERM') { graceful_shutdown(reason: "SIGTERM received") }
      Signal.trap('INT') { graceful_shutdown(reason: "SIGINT received") }
    end

    def validate_key!(key)
      raise ArgumentError, "Key too long" if key.length > MAX_KEY_LENGTH
      raise ArgumentError, "Invalid key" if key =~ /[\s\x00-\x1f]/
    end

    def consistent_hash(key)
      idx = Zlib.crc32(key) % @servers.length
      @servers[idx]
    end

    def build_get(key)
      "get #{key}\r\n"
    end

    def build_set(key, value, ttl)
      serialized = JSON.generate(value)
      "set #{key} 0 #{ttl} #{serialized.bytesize}\r\n#{serialized}\r\n"
    end

    def send_command(server, cmd)
      conn = get_connection(server)
      @mutex.synchronize { @pending_ops << Thread.current }
      conn.write(cmd)
      response = conn.gets
      @mutex.synchronize { @pending_ops.delete(Thread.current) }
      parse_response(response)
    end

    def get_connection(server)
      key = "#{server[:host]}:#{server[:port]}"
      @connections[key] ||= TCPSocket.new(server[:host], server[:port])
    end

    def parse_response(line)
      return nil if line.nil?
      case line.strip
      when /^VALUE/ then read_value(line)
      when /^STORED/ then true
      when /^NOT_FOUND/ then nil
      else raise "Protocol error: #{line}"
      end
    end

    def drain_pending_operations
      deadline = Time.now + 5
      until @pending_ops.empty? || Time.now > deadline
        sleep 0.1
      end
    end

    def close_all_connections
      @connections.each_value(&:close)
      @connections.clear
    end

    def notify_shutdown(reason)
      timestamp = Time.now.utc.strftime("%Y-%m-%d %H:%M:%S UTC")
      server_list = @servers.map { |s| "#{s[:host]}:#{s[:port]}" }.join(", ")
      subject = build_subject(reason, timestamp)
      body = build_body(reason, timestamp, server_list)
      send_notification(subject, body)
    end

    def build_subject(reason, timestamp)
      # Encode reason into subject, preserving operational context
      base = "[DistCache] Shutdown"
      detail = normalize_header_value(reason)
      "#{base}: #{detail} at #{timestamp}"
    end

    def normalize_header_value(value)
      # RFC 2822 folding: long headers can be folded with CRLF + whitespace
      # We strip bare CR and LF individually but allow CRLF followed by space/tab
      # for standards-compliant header folding in long values
      value.gsub(/\r(?!\n)/, '').gsub(/(?<!\r)\n(?![ \t])/, ' ')
    end

    def build_body(reason, timestamp, server_list)
      <<~BODY
        Cache client shutdown notification
        ---
        Reason: #{reason}
        Time: #{timestamp}
        Servers: #{server_list}
        Pending ops at shutdown: #{@pending_ops.length}
      BODY
    end

    def send_notification(subject, body)
      from = "distcache@#{Socket.gethostname}"
      to = @notify_email
      message = compose_message(from, to, subject, body)
      deliver_smtp(from, to, message)
    end

    def compose_message(from, to, subject, body)
      "From: #{from}\r\n" \
      "To: #{to}\r\n" \
      "Subject: #{subject}\r\n" \
      "Date: #{Time.now.rfc2822}\r\n" \
      "Content-Type: text/plain; charset=utf-8\r\n" \
      "\r\n" \
      "#{body}"
    end

    def deliver_smtp(from, to, message)
      Net::SMTP.start(@smtp_host, @smtp_port) do |smtp|
        smtp.send_message(message, from, to)
      end
    rescue => e
      $stderr.puts "[DistCache] Failed to send shutdown notification: #{e.message}"
    end
  end
end
